introspectionQuery:
query IntrospectionQuery {
  __schema {

    queryType { name kind }
    mutationType { name kind }
    subscriptionType { name kind }
    types {
      ...FullType
    }
    directives {
      name
      description



      locations
      args {
        ...InputValue
      }
    }
  }
}

fragment FullType on __Type {
  kind
  name
  description


  fields(includeDeprecated: true) {
    name
    description
    args {
      ...InputValue
    }
    type {
      ...TypeRef
    }
    isDeprecated
    deprecationReason
  }
  inputFields {
    ...InputValue
  }
  interfaces {
    ...TypeRef
  }
  enumValues(includeDeprecated: true) {
    name
    description
    isDeprecated
    deprecationReason
  }
  possibleTypes {
    ...TypeRef
  }
}

fragment InputValue on __InputValue {
  name
  description
  type { ...TypeRef }
  defaultValue


}

fragment TypeRef on __Type {
  kind
  name
  ofType {
    name
    kind
    ofType {
      name
      kind
      ofType {
        name
        kind
        ofType {
          name
          kind
          ofType {
            name
            kind
            ofType {
              name
              kind
              ofType {
                name
                kind
                ofType {
                  name
                  kind
                  ofType {
                    name
                    kind
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

sources.query:
query {
  viewer {
    login
    repositories(first: 10) {
      totalCount
      nodes {
        name
      }
    }
  }
}

query {
  viewer {
    login
    repository(name: "metapixel") {
      pullRequests(first:10) {
        nodes {
          state
        }
      }
    }
  }
}

query {
  viewer {
    ... UserFragment
    repository(name: "metapixel") {
      pullRequests(first:10) {
        nodes {
          state
        }
      }
    }
  }
}

fragment UserFragment on User {
  login
  name
}

query test($more: Boolean!) {
  viewer {
    login
    name @include(if: $more)
  }
}

query {
  resource(url: "https://github.com/quicktype/quicktype") {
    url
    ... on User {
      login
    }
  }
}

{
  viewer {
    login
    starredRepositories {
      totalCount
    }
    repositories(first: 3) {
      edges {
        node {
          name
          stargazers {
            totalCount
          }
          forks {
            totalCount
          }
          watchers {
            totalCount
          }
          issues(states:[OPEN]) {
            totalCount
          }
        }
      }
    }
  }
}

{
  repository(owner: "quicktype", name: "quicktype") {
    nameWithOwner,
    n303: issueOrPullRequest(number: 303) {
      ... IOPR
    },
    n307: issueOrPullRequest(number: 307) {
      ... IOPR
    }
  }
}

fragment IOPR on IssueOrPullRequest {
  ... on Issue {
    title
    state
  }
  ... on PullRequest {
    title
    merged
  }  
}

mutation AddReaction($input: AddReactionInput!){
  addReaction(input: $input){
    clientMutationId
    reaction {
      content
    }
    subject {
      viewerCanReact
      reactionGroups {
          content
      }
    }
  }
}

